/**
 * MarketSettingsCard component for admin market settings configuration
 * - Portions generated by AI
 */

import { useState, useEffect, useCallback } from 'react';
import { TrendingUp, Save, RefreshCw, ExternalLink } from 'lucide-react';
import apiClient from '@/api/client';
import type { MarketSettings } from '@/types';

interface MarketSettingsCardProps {
  isReady: boolean;
}

export function MarketSettingsCard({ isReady }: MarketSettingsCardProps) {
  const [settings, setSettings] = useState<MarketSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  // Form state - stored as percentage for display (e.g., 3.67 for 3.67%)
  const [riskFreeRatePercent, setRiskFreeRatePercent] = useState(3.67);

  // Load settings
  useEffect(() => {
    if (!isReady) return;

    const loadSettings = async () => {
      setLoading(true);
      setError(null);
      try {
        const data = await apiClient.getMarketSettings();
        setSettings(data);
        setRiskFreeRatePercent(data.risk_free_rate_percent);
      } catch (err: any) {
        console.error('Failed to load market settings:', err);
        setError('Failed to load market settings');
      } finally {
        setLoading(false);
      }
    };

    loadSettings();
  }, [isReady]);

  // Save settings
  const handleSave = useCallback(async () => {
    setSaving(true);
    setError(null);
    setSuccess(false);

    try {
      // Convert percentage to decimal for API
      const riskFreeRate = riskFreeRatePercent / 100;
      const updated = await apiClient.updateMarketSettings({
        risk_free_rate: riskFreeRate,
      });
      setSettings(updated);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err: any) {
      console.error('Failed to save market settings:', err);
      setError(err.response?.data?.detail || 'Failed to save market settings');
    } finally {
      setSaving(false);
    }
  }, [riskFreeRatePercent]);

  // Check if form has changes
  const hasChanges =
    settings && Math.abs(riskFreeRatePercent - settings.risk_free_rate_percent) > 0.001;

  if (loading) {
    return (
      <div className="card">
        <div className="flex items-center gap-2 mb-4">
          <TrendingUp size={20} className="text-primary-400" />
          <h2 className="text-xl font-semibold">Market Settings</h2>
        </div>
        <div className="flex items-center justify-center py-8 text-gray-400">
          <RefreshCw size={20} className="animate-spin mr-2" />
          Loading...
        </div>
      </div>
    );
  }

  return (
    <div className="card">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <TrendingUp size={20} className="text-primary-400" />
          <h2 className="text-xl font-semibold">Market Settings</h2>
        </div>
        {settings?.updated_at && (
          <span className="text-xs text-gray-500">
            Last updated: {new Date(settings.updated_at).toLocaleString()}
          </span>
        )}
      </div>

      {error && (
        <div className="mb-4 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
          {error}
        </div>
      )}

      {success && (
        <div className="mb-4 p-3 bg-green-500/10 border border-green-500/30 rounded-lg text-green-400 text-sm">
          Market settings saved successfully!
        </div>
      )}

      <div className="space-y-4">
        {/* Risk-Free Rate Input */}
        <div className="p-3 bg-dark-800 rounded-lg">
          <label className="block text-sm font-medium text-white mb-2">
            Risk-Free Rate
          </label>
          <p className="text-xs text-gray-500 mb-3">
            Used for Black-Scholes Greeks calculations when API data is unavailable
          </p>
          <div className="flex items-center gap-3">
            <input
              type="number"
              min={0}
              max={100}
              step={0.01}
              value={riskFreeRatePercent}
              onChange={(e) => setRiskFreeRatePercent(parseFloat(e.target.value) || 0)}
              className="w-24 px-3 py-2 bg-dark-700 border border-white/10 rounded-lg text-white text-center"
            />
            <span className="text-gray-400 text-sm">%</span>
            <span className="text-gray-500 text-xs ml-auto">
              (Decimal: {(riskFreeRatePercent / 100).toFixed(4)})
            </span>
          </div>
        </div>

        {/* FRED Reference Link */}
        <div className="p-3 bg-dark-800/50 rounded-lg border border-white/5">
          <div className="flex items-start gap-2">
            <ExternalLink size={16} className="text-primary-400 mt-0.5 flex-shrink-0" />
            <div>
              <p className="text-sm text-gray-300">
                Get the current 3-Month Treasury Rate from FRED:
              </p>
              <a
                href="https://fred.stlouisfed.org/series/DGS3MO"
                target="_blank"
                rel="noopener noreferrer"
                className="text-primary-400 hover:text-primary-300 text-sm underline mt-1 inline-block"
              >
                fred.stlouisfed.org/series/DGS3MO
              </a>
              <p className="text-xs text-gray-500 mt-2">
                Updated daily by the Federal Reserve. Check periodically and update the rate above.
              </p>
            </div>
          </div>
        </div>

        {/* Save Button */}
        <button
          onClick={handleSave}
          disabled={saving || !hasChanges}
          className={`w-full flex items-center justify-center gap-2 py-2.5 rounded-lg font-medium transition-colors ${
            hasChanges
              ? 'bg-primary-500 hover:bg-primary-600 text-white'
              : 'bg-gray-700 text-gray-400 cursor-not-allowed'
          }`}
        >
          {saving ? (
            <>
              <RefreshCw size={16} className="animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save size={16} />
              Save Changes
            </>
          )}
        </button>
      </div>
    </div>
  );
}
